142:func topDebugLogError(records []eval.Record) (string, int) {
143:	counts := make(map[string]int)
144:	for _, rec := range records {
145:		if rec.Type != "tool_result" {
146:			continue
147:		}
148:		errText, _ := rec.Data["error"].(string)
149:		if strings.TrimSpace(errText) == "" {
150:			continue
151:		}
152:		summary, _ := rec.Data["summary"].(string)
153:		summary = strings.TrimSpace(summary)
154:		if summary == "" {
155:			summary = firstDebugLogLine(errText)
156:		}
157:		counts[summary]++
158:	}
159:	type pair struct {
160:		Summary string
161:		Count   int
162:	}
163:	pairs := make([]pair, 0, len(counts))
164:	for summary, count := range counts {
165:		pairs = append(pairs, pair{Summary: summary, Count: count})
166:	}
167:	sort.Slice(pairs, func(i, j int) bool {
168:		if pairs[i].Count == pairs[j].Count {
169:			return pairs[i].Summary < pairs[j].Summary
170:		}
171:		return pairs[i].Count > pairs[j].Count
172:	})
173:	if len(pairs) == 0 {
174:		return "", 0
175:	}
176:	return pairs[0].Summary, pairs[0].Count
177:}
